import React, { useState } from 'react';
import axios from 'axios';

function FileUpload() {
  const [file, setFile] = useState(null);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');
  const [parentFolderId, setParentFolderId] = useState('');

  const handleFileChange = (e) => {
    setFile(e.target.files[0]);
    setMessage('');
    setError('');
  };

  const handleParentFolderChange = (e) => {
    setParentFolderId(e.target.value);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    if (!file) {
      setError('Please select a file to upload');
      return;
    }
    
    setLoading(true);
    setMessage('');
    setError('');
    
    const formData = new FormData();
    formData.append('file', file);
    
    if (parentFolderId) {
      formData.append('parentFolderId', parentFolderId);
    }
    
    try {
      const response = await axios.post('/api/files/upload', formData, {
        headers: {
          'Content-Type': 'multipart/form-data'
        }
      });
      
      setMessage('File uploaded successfully!');
      setFile(null);
      
      // Reset the file input
      const fileInput = document.getElementById('fileInput');
      if (fileInput) {
        fileInput.value = '';
      }
      
      // Trigger a refresh of the file list
      // This could be done by lifting state up or using a context
      // For simplicity, we'll just emit a custom event
      window.dispatchEvent(new CustomEvent('fileUploaded'));
    } catch (err) {
      setError(err.response?.data || 'Failed to upload file. Please try again.');
      console.error('Error uploading file:', err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="card" style={{ marginBottom: '20px' }}>
      <h2>Upload File</h2>
      
      {message && (
        <div className="alert alert-success">
          {message}
        </div>
      )}
      
      {error && (
        <div className="alert alert-danger">
          {error}
        </div>
      )}
      
      <form onSubmit={handleSubmit}>
        <div className="form-group">
          <label htmlFor="fileInput">Select File</label>
          <input
            type="file"
            className="form-control"
            id="fileInput"
            onChange={handleFileChange}
          />
        </div>
        
        <div className="form-group">
          <label htmlFor="parentFolderId">Parent Folder ID (optional)</label>
          <input
            type="text"
            className="form-control"
            id="parentFolderId"
            value={parentFolderId}
            onChange={handleParentFolderChange}
            placeholder="Leave empty for root folder"
          />
        </div>
        
        <button 
          type="submit" 
          className="btn" 
          disabled={loading || !file}
        >
          {loading ? 'Uploading...' : 'Upload'}
        </button>
      </form>
    </div>
  );
}

export default FileUpload;
